# -*- coding: utf-8 -*-
"""把 `raw/pdf/si/` 下的 SI 压缩包解成 `<stem>.bundle/` 目录（保留内部结构）。

## 为什么要有这一步

出版商常把**计算数据**（VASP POSCAR / CIF / 原始数据表）打包成 zip 当作 Supplementary
Information。zip 留在盘上时：Obsidian 看不到里面的结构文件、卡片里的 `si_status: present`
说的是「有一个 zip」而不是「有可查询的数据」。解包后按目录归类，`<stem>.si2.bundle/`
里就是论文作者给的原始层级（如按金属 Co2/CoCu/CoNi 分组）。

## 命名约定

| 输入 | 输出 |
|---|---|
| `<stem>.si.zip`   | `<stem>.si.bundle/` |
| `<stem>.si2.zip`  | `<stem>.si2.bundle/` |

- 解包后**逐条复算**文件数与字节数，与 zip 目录项一致才算成功（中途失败留在 `<bundle>.part/`）。
- 单个公共顶层目录（`Supporting Information 1/` 这类无信息容器）会被剥掉；多级结构原样保留。
- 原 zip **移入** `_archive/lit-watch/<YYYYMMDD>-si-zips/`（只移不删），便于回滚。

## 用法

    python tools/lit_si_unzip.py              # 干跑：列出每个 zip 会解出什么
    python tools/lit_si_unzip.py --apply      # 落盘
    python tools/lit_si_unzip.py --selftest   # 自检（在合成目录里跑，不碰真库）
"""
from __future__ import annotations

import argparse
import datetime
import os
import shutil
import sys
import tempfile
import zipfile

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def default_si_dir() -> str:
    return os.path.join(ROOT, "raw", "pdf", "si")


def default_archive_dir() -> str:
    stamp = datetime.date.today().strftime("%Y%m%d")
    return os.path.join(ROOT, "_archive", "lit-watch", f"{stamp}-si-zips")


def common_top(names) -> str:
    """若全部成员都在同一个一级目录下，返回 `目录名/`；否则返回空串。"""
    tops = {n.split("/", 1)[0] for n in names if "/" in n}
    if len(tops) != 1:
        return ""
    top = tops.pop() + "/"
    return top if all(n.startswith(top) for n in names) else ""


def unzip_one(zip_path: str, si_dir: str, archive_dir: str, apply: bool = False) -> dict:
    """解一个 zip。返回 {ok, bundle, files, bytes, reason}。不抛异常（除 IO 致命错误）。"""
    base = os.path.basename(zip_path)
    stem = base[:-len(".zip")] if base.lower().endswith(".zip") else base
    bundle = os.path.join(si_dir, stem + ".bundle")
    out = {"zip": zip_path, "bundle": bundle, "ok": False, "files": 0, "bytes": 0, "reason": ""}

    try:
        z = zipfile.ZipFile(zip_path)
    except Exception as e:                                        # noqa: BLE001
        out["reason"] = f"打不开：{type(e).__name__}"
        return out

    with z:
        bad = z.testzip()
        if bad is not None:
            out["reason"] = f"CRC 损坏：{bad}"
            return out
        members = [i for i in z.infolist() if not i.is_dir()]
        if not members:
            out["reason"] = "空 zip"
            return out
        top = common_top([i.filename for i in z.infolist()])
        n_exp = len(members)
        b_exp = sum(i.file_size for i in members)
        out.update({"files": n_exp, "bytes": b_exp, "top": top})

        if os.path.exists(bundle):
            out["reason"] = "目标目录已存在"
            return out
        if not apply:
            out["ok"] = True
            out["reason"] = "dry-run"
            return out

        tmp = bundle + ".part"
        if os.path.exists(tmp):
            shutil.rmtree(tmp)
        os.makedirs(tmp)
        for i in members:
            rel = i.filename[len(top):] if top else i.filename
            dst = os.path.join(tmp, *rel.split("/"))
            os.makedirs(os.path.dirname(dst) or tmp, exist_ok=True)
            with z.open(i) as src, open(dst, "wb") as fd:
                shutil.copyfileobj(src, fd)

    got = [os.path.join(dp, f) for dp, _, fs in os.walk(tmp) for f in fs]
    got_b = sum(os.path.getsize(p) for p in got)
    if len(got) != n_exp or got_b != b_exp:
        out["reason"] = f"复算不符：{len(got)}/{n_exp} 文件, {got_b}/{b_exp} 字节（半成品在 {tmp}）"
        return out
    os.rename(tmp, bundle)
    os.makedirs(archive_dir, exist_ok=True)
    dst_zip = os.path.join(archive_dir, base)
    if os.path.exists(dst_zip):
        out["reason"] = f"归档已有同名 zip，未移动：{dst_zip}"
    else:
        shutil.move(zip_path, dst_zip)
    out["ok"] = True
    out["reason"] = "ok"
    return out


def find_zips(si_dir: str):
    if not os.path.isdir(si_dir):
        return []
    return sorted(os.path.join(si_dir, n) for n in os.listdir(si_dir)
                  if n.lower().endswith(".zip") and ".si" in n.lower())


def selftest() -> int:
    """合成目录自检：正例（多级结构 + 公共顶层）与反例（目标已存在、空 zip）。"""
    fails = []
    with tempfile.TemporaryDirectory() as td:
        si = os.path.join(td, "si")
        ar = os.path.join(td, "arch")
        os.makedirs(si)
        stem = "A Paper - J. Test - 2026"
        zp = os.path.join(si, stem + ".si2.zip")
        with zipfile.ZipFile(zp, "w", zipfile.ZIP_DEFLATED) as z:
            z.writestr("Supporting Information 1/", "")
            z.writestr("Supporting Information 1/Co2/a.vasp", "x" * 100)
            z.writestr("Supporting Information 1/CoCu/b.vasp", "y" * 50)
        r = unzip_one(zp, si, ar, apply=True)
        bundle = os.path.join(si, stem + ".si2.bundle")
        if not r["ok"]:
            fails.append(f"正例未成功：{r['reason']}")
        if not os.path.isdir(bundle):
            fails.append("未生成 .si2.bundle 目录")
        else:
            got = sorted(os.path.relpath(os.path.join(dp, f), bundle)
                         for dp, _, fs in os.walk(bundle) for f in fs)
            if got != ["Co2" + os.sep + "a.vasp", "CoCu" + os.sep + "b.vasp"] and \
               got != [os.path.join("Co2", "a.vasp"), os.path.join("CoCu", "b.vasp")]:
                fails.append(f"内部结构不符：{got}")
        if os.path.exists(zp):
            fails.append("原 zip 未移入归档")
        if not os.path.exists(os.path.join(ar, stem + ".si2.zip")):
            fails.append("归档里没有原 zip")
        # 反例 1：同名 bundle 已存在 → 不得覆盖
        r2 = unzip_one(os.path.join(ar, stem + ".si2.zip"), si, ar, apply=True)
        if r2["ok"] or "已存在" not in r2["reason"]:
            fails.append(f"反例（目标已存在）未拦住：{r2}")
        # 反例 2：空 zip
        empty = os.path.join(si, "Empty Paper.si.zip")
        with zipfile.ZipFile(empty, "w"):
            pass
        r3 = unzip_one(empty, si, ar, apply=True)
        if r3["ok"] or "空 zip" not in r3["reason"]:
            fails.append(f"反例（空 zip）未拦住：{r3}")
        # 反例 3：非 zip
        junk = os.path.join(si, "Junk.si.zip")
        open(junk, "w", encoding="utf-8").write("not a zip")
        r4 = unzip_one(junk, si, ar, apply=True)
        if r4["ok"] or "打不开" not in r4["reason"]:
            fails.append(f"反例（非 zip）未拦住：{r4}")

    for f in fails:
        print("  [FAIL]", f)
    print(f"lit_si_unzip selftest: {'PASS' if not fails else 'FAIL'} ({len(fails)} 项失败)")
    return 0 if not fails else 1


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description="解包 raw/pdf/si 下的 SI zip")
    ap.add_argument("--apply", action="store_true", help="真正落盘（默认干跑）")
    ap.add_argument("--si-dir", default="", help="SI 目录（默认 raw/pdf/si）")
    ap.add_argument("--archive-dir", default="", help="原 zip 归档目录（默认 _archive/lit-watch/<日期>-si-zips）")
    ap.add_argument("--selftest", action="store_true", help="自检")
    args = ap.parse_args(argv)
    if args.selftest:
        return selftest()

    si = args.si_dir or default_si_dir()
    ar = args.archive_dir or default_archive_dir()
    zips = find_zips(si)
    if not zips:
        print(f"没有待解包的 SI zip（{si}）")
        return 0
    ok = 0
    for zp in zips:
        r = unzip_one(zp, si, ar, apply=args.apply)
        tag = "OK  " if r["ok"] else "FAIL"
        extra = f"，剥掉公共顶层 {r['top']!r}" if r.get("top") else ""
        print(f"{tag} {os.path.basename(zp)}")
        print(f"     -> {os.path.basename(r['bundle'])}/  "
              f"({r['files']} 文件, {r['bytes']/1e6:.2f} MB{extra})")
        if r["reason"] not in ("ok", "dry-run"):
            print(f"     ! {r['reason']}")
        ok += 1 if r["ok"] else 0
    print(f"\n{'written' if args.apply else 'planned'}: {ok} | 目标 {len(zips)}")
    return 0 if ok == len(zips) else 1


if __name__ == "__main__":
    sys.exit(main())
